def free_edges(T, dec=9):
    from collections import Counter
    ce = Counter()
    for t in T:
        k = [tuple(np.round(v,dec)) for v in t]
        for a,b in ((0,1),(1,2),(2,0)): ce[tuple(sorted((k[a],k[b])))] += 1
    return sum(1 for v in ce.values() if v != 2), len(ce)
